input.command:
mkdir -p src/inngest "src/app/api/inngest" && cat > src/inngest/client.ts <<'EOF'
import { Inngest } from "inngest";

export const inngest = new Inngest({ id: "notely" });
EOF
cat > src/inngest/functions.ts <<'EOF'
import { inngest } from "./client";

export const USER_CREATED_EVENT = "notely/user.created";

export const REMINDER_DELAY = "10m";

export const userReminder = inngest.createFunction(
  { id: "user-reminder", retries: 4, triggers: [{ event: USER_CREATED_EVENT }] },
  async ({ event, step }) => {
    // Durable sleep: survives restarts and doesn't hold a serverless invocation open.
    await step.sleep("wait-before-reminder", REMINDER_DELAY);

    // Retried with backoff by Inngest if it throws.
    await step.run("log-reminder", async () => {
      const { userId, email, name } = event.data;
      console.log(`[reminder] ${name} <${email}> (user ${userId}) signed up ${REMINDER_DELAY} ago`);
    });
  },
);

export const functions = [userReminder];
EOF
cat > src/app/api/inngest/route.ts <<'EOF'
import { serve } from "inngest/next";
import { inngest } from "@/inngest/client";
import { functions } from "@/inngest/functions";

export const { GET, POST, PUT } = serve({ client: inngest, functions });
EOF
python3 - <<'EOF'
p='src/lib/users.ts'
s=open(p).read()
s='import { inngest } from "@/inngest/client";\nimport { USER_CREATED_EVENT } from "@/inngest/functions";\n\n'+s
s=s.replace('''export async function getUser''','''export async function createUser(input: { email: string; name: string }): Promise<User> {
  const user: User = {
    id: String(users.length + 1),
    email: input.email,
    name: input.name,
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);

  // Schedules the 10-minute reminder job (see src/inngest/functions.ts).
  // A scheduling failure must not fail user creation.
  try {
    await inngest.send({
      name: USER_CREATED_EVENT,
      data: { userId: user.id, email: user.email, name: user.name },
    });
  } catch (err) {
    console.error("Failed to schedule user reminder", err);
  }

  return user;
}

export async function getUser''',1)
open(p,'w').write(s)
EOF
cat > .env.example <<'EOF'
# Inngest (https://app.inngest.com). Not needed locally when using the dev server:
#   npx inngest-cli@latest dev -u http://localhost:3000/api/inngest
# For local dev set INNGEST_DEV=1 instead.
INNGEST_EVENT_KEY=placeholder-event-key
INNGEST_SIGNING_KEY=signkey-prod-placeholder
EOF
printf '!.env.example\n' >> .gitignore
grep -n '"@/' tsconfig.json; npx tsc --noEmit 2>&1 | head; npm run lint 2>&1 | tail -8

